};

const methodOrder: MethodKey[] = ['features', 'cnn', 'opentslm', 'qwen'];
const percent = (value: number) => value * 100;
const answeredWindows = Math.round(audited.opentslm.usable_summary_rate * comparison.window_count);

const results = {
