    """Summarise exact submitted samples; annotations are never used as evidence."""
    rows = []
    for channel in series:
        values = channel["values"]
        if values:
            lo, hi = min(values), max(values)
            rows.append({"channel": channel["channelId"], "range": hi - lo,
