  1	import { selectWindow } from '../lib/data';
  2	import type { DemoData, EvidenceLink, Interval } from '../types';
  3	import { structuredPrediction } from './predictionBrief';
  4	import { reviewPrediction } from './predictionReview';
  5	
  6	export type InvestigationAnswer = {
  7	  question: string; interval: Interval; playhead: number; replayCursor?: number; text: string;
  8	  mode: 'local' | 'assistant'; source: string; evidence: EvidenceLink[];
  9	  modelId?: string; modelRevision?: string; inputTrace?: unknown; modelOutput?: string;
 10	};
 11	
 12	function inputReceiptIssue(receipt: unknown, recordingId: string, interval: Interval): string | undefined {
 13	  if (!receipt || typeof receipt !== 'object') return 'The service did not provide an input receipt.';
 14	  const value = receipt as {
 15	    samplesPerChannel?: unknown;
 16	    inputSha256?: unknown;
 17	    window?: { channelIds?: unknown; recordingId?: unknown; startSec?: unknown; endSec?: unknown };
 18	  };
 19	  const expectedChannels = Array.from({ length: 7 }, (_, index) => `joint_${index + 1}`);
 20	  const channelIds = value.window?.channelIds;
 21	  if (value.samplesPerChannel !== 1024) return 'The input receipt does not confirm 1,024 samples per channel.';
 22	  if (!Array.isArray(channelIds) || channelIds.join(',') !== expectedChannels.join(',')) {
 23	    return 'The input receipt does not confirm canonical joint_1 through joint_7 channel order.';
 24	  }
 25	  if (
 26	    value.window?.recordingId !== recordingId
 27	    || value.window.startSec !== interval.start
 28	    || value.window.endSec !== interval.end
 29	  ) {
 30	    return 'The input receipt does not match this recording and selected interval.';
 31	  }
 32	  if (typeof value.inputSha256 !== 'string' || !/^[a-f0-9]{64}$/i.test(value.inputSha256)) {
 33	    return 'The input receipt does not include a valid input hash.';
 34	  }
 35	  return undefined;
 36	}
 37	
 38	export function buildInvestigationReport(data: DemoData, datasetId: string, answer: InvestigationAnswer) {
 39	  if (answer.interval.end > answer.playhead) throw new Error('The investigation extends beyond its replay cursor.');
 40	  const window = selectWindow(data, answer.interval);
 41	  const measurements = window.channels.map(channel => {
 42	    let minimum = Infinity, maximum = -Infinity, peakIndex = 0;
 43	    channel.values.forEach((value, index) => {
 44	      minimum = Math.min(minimum, value); maximum = Math.max(maximum, value);
 45	      if (Math.abs(value) > Math.abs(channel.values[peakIndex])) peakIndex = index;
 46	    });
 47	    return { channelId: channel.id, name: channel.name, unit: channel.unit, minimum, maximum,
 48	      range: maximum - minimum, absolutePeak: Math.abs(channel.values[peakIndex]),
 49	      signedPeak: channel.values[peakIndex], peakTimeSec: window.times[peakIndex] };
 50	  });
 51	  const receiptIssue = answer.mode === 'assistant'
 52	    ? inputReceiptIssue(answer.inputTrace, data.recording.id, answer.interval)
 53	    : undefined;
 54	  const predictionReview = answer.mode === 'assistant' ? reviewPrediction(data, answer.interval, answer.modelOutput) : undefined;
 55	  return {
 56	    schemaVersion: 1, kind: 'trace_retrospective_investigation',
 57	    recording: { datasetId, recordingId: data.recording.id, sourceUrl: data.recording.sourceUrl },
 58	    question: answer.question,
 59	    window: { startSec: answer.interval.start, endSec: answer.interval.end,
 60	      convention: 'half-open [start, end)', playheadSec: answer.playhead,
 61	      analysisHorizonSec: answer.playhead, replayCursorSec: answer.replayCursor ?? answer.playhead,
 62	      resolution: window.resolution, sampleRateHz: window.sampleRateHz, samplesPerChannel: window.times.length },
 63	    publisherAnnotations: data.events.filter(e => e.timeSeconds >= answer.interval.start && e.timeSeconds < answer.interval.end),
 64	    measurements: { origin: 'deterministic_calculation', method: 'sampled min, max, range and absolute peak', channels: measurements },
 65	    interpretation: { origin: answer.mode === 'local' ? 'deterministic_calculation' : 'generated_prediction',
 66	      answer: answer.text, source: answer.source, modelId: answer.modelId ?? null,
 67	      modelRevision: answer.modelRevision ?? null, rawModelOutput: answer.modelOutput ?? null,
 68	      rawModelOutputTrust: answer.modelOutput ? 'unverified_generated_text_not_annotation_or_measurement' : null,
 69	      structuredPrediction: answer.mode === 'assistant' ? structuredPrediction(answer.modelOutput) ?? null : null,
 70	      inputReceipt: answer.inputTrace ?? null, evidence: answer.evidence },
 71	    reviewNotes: predictionReview ? [predictionReview.note] : [],
 72	    limitations: [
 73	      'Recorded contact-event triage; no verified root cause, safety decision or repair recommendation.',
 74	      'Publisher annotations, measured quantities and generated predictions are distinct evidence sources.',
 75	      'Strong torque response does not identify the physical contact location.',
 76	      ...(window.resolution === 'display' ? ['Measurements use reduced display samples; short peaks may be missing.'] : []),
 77	      ...(answer.mode === 'assistant' && !answer.modelRevision ? ['The service did not provide a model revision.'] : []),
 78	      ...(receiptIssue ? [receiptIssue] : []),
 79	      ...(answer.mode === 'assistant' && answer.modelOutput ? ['Raw model output is preserved for audit and may disagree with publisher annotations.'] : []),
 80	    ],
 81	  };
 82	}
