 84	type InvestigationReport = ReturnType<typeof buildInvestigationReport>;
 85	
 86	function markdownText(value: unknown): string {
 87	  return String(value ?? '')
 88	    .replace(/\\/g, '\\\\')
 89	    .replace(/([`*_[\]<>|])/g, '\\$1')
 90	    .replace(/\s+/g, ' ')
 91	    .trim();
 92	}
 93	
 94	function markdownLink(url: string): string {
 95	  return `<${url.replace(/</g, '%3C').replace(/>/g, '%3E')}>`;
 96	}
 97	
 98	function fixed(value: number, digits = 3): string {
 99	  return Number.isFinite(value) ? value.toFixed(digits) : 'unavailable';
100	}
